-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2021, revalida-2021): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 60 correções de texto em 29 questões (40 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2021';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2021_1_q004","code":"REV-2021-Q004","campos":{"statement":{"antes_md5":"2337329784afa2d67d9746a56aace00d","depois":"Paciente teve parto cesárea há 8 dias e retorna à maternidade com queixa de febre alta há 2 dias, acompanhada de calafrios nas últimas horas. Refere ainda dor intensa em andar inferior do abdome. A loquiação está escassa, mas apresenta odor fétido. Ao exame: regular estado geral, temperatura 39 ºC, PA = 100 x 60 mmHg, FC = 120 bpm, útero no nível da cicatriz umbilical, amolecido e doloroso à palpação. Cicatriz de cesariana seca e limpa. Mamas lactantes, com sinais de ingurgitamento mamário e fissura mamilar à esquerda, mas sem evidência de mastite ou abscesso mamário. Ultrassonografia não evidenciou sinais ecográficos de conteúdo anormal na cavidade uterina ou na cavidade abdominal. Hemograma com leucocitose e desvio à esquerda. A conduta indicada para esse caso é"}}},{"id":"revalida_2021_1_q005","code":"REV-2021-Q005","campos":{"statement":{"antes_md5":"c295d57bf0574f783c4aeb6180c129a3","depois":"Paciente de 68 anos de idade, do sexo masculino, hipertenso, vem em consulta devido à queixa de diminuição da acuidade auditiva e sensação de plenitude auditiva à direita. Paciente nega história de perfuração timpânica ou de cirurgia otológica. Ao realizar a otoscopia, o médico de família visualiza a membrana timpânica translúcida à esquerda e identifica uma rolha de cerume no conduto auditivo direito, impedindo a visualização da membrana timpânica. O médico orienta o uso de emolientes para remoção do cerume e retorno em 5 dias. No retorno, a rolha de cerume ainda obstrui o conduto auditivo direito completamente. Como deverá ser feita a remoção do cerume por irrigação?"}}},{"id":"revalida_2021_1_q018","code":"REV-2021-Q018","campos":{"statement":{"antes_md5":"66c656a2a517dfe382506566be6362b9","depois":"Uma mulher de 30 anos de idade vem a consulta com o endocrinologista para acompanhamento de hipotireoidismo. Há 6 meses ela procurou o médico da Unidade Básica de Saúde próxima a sua residência devido à constipação (evacuava a cada 3 dias, com fezes ressecadas e com dor ao evacuar). A paciente era sedentária e apresentava erros alimentares evidentes, com baixa ingesta de água durante o dia e pouco consumo de frutas e verduras. O médico orientou ajustes na alimentação, ingesta hídrica e necessidade de atividade física regular, assim como dosagem de TSH e T4 livre. Após 2 meses a paciente retornou, tendo aderido às recomendações, resultando na solução do quadro de constipação (evacuava diariamente, sem dor, com fezes bem formadas), contudo, os exames laboratoriais demonstraram: TSH = 5,5 mUI/mL (valor de referência: 0,4 a 4,5 mUI/L) e T4 livre = 1,0 (valor de referência: 0,7 a 1,8 ng/dL). O médico repetiu os exames, que indicaram: TSH = 5,3 mUI/L (valor de referência: 0,4 a 4,5 mUI/mL) e T4 livre = 1,1 (valor de referência: 0,7 a 1,8 ng/dL). Diante da persistência dos exames alterados, o médico prescreveu levotiroxina 50 mcg/dia e encaminhou ao especialista. Durante a consulta com o endocrinologista, a paciente está assintomática, com tireoide não palpável e índice de massa corpórea de 22 kg/m², contudo, não havia iniciado a levotiroxina, pois possuía receio de possíveis efeitos adversos. Considerando o que foi apresentado, o endocrinologista deve"}}},{"id":"revalida_2021_1_q019","code":"REV-2021-Q019","campos":{"statement":{"antes_md5":"f975f439a8e5792d81b889759cfa8b26","depois":"Lactente, com 6 meses de idade, está sendo atendido na Estratégia da Saúde para puericultura. A médica identifica o registro no cartão apenas da vacina Influenza, que foi feita na rede particular de imunização. As demais vacinas a serem administradas até o 5.º mês estavam todas registradas na caderneta. Nesse caso, quais são as vacinas recomendadas para a idade conforme o Programa Nacional de Imunização?"}}},{"id":"revalida_2021_1_q022","code":"REV-2021-Q022","campos":{"statement":{"antes_md5":"cab98fe70f8737508db120979b452085","depois":"Um homem com 42 anos de idade foi operado em hospital secundário com quadro de apendicite aguda com necrose e abscesso em apêndice retrocecal (Fase III), sendo realizada apendicectomia e drenagem do abscesso por incisão mediana infraumbilical. No terceiro dia de pós-operatório começou a apresentar picos diários de aumento da temperatura axilar (38,5 °C) apesar dos antibióticos prescritos (ceftriaxona e metronidazol). A incisão encontrava-se com bom aspecto, foram encontrados 15 200 leucócitos/mm³ (referência: 3 500 a 10 500) e alteração na contagem diferencial dos leucócitos, com 5% de bastonetes no sangue periférico (referência: 0 a 2%). A proteína C reativa era de 15 mg/L (referência: menor que 3). Relatava dor ao tentar fletir a coxa direita e o examinador exercia discreta pressão contrária ao movimento, a ausculta pulmonar era normal e os ruídos hidroaéreos estavam presentes. Com base nos dados apresentados, qual é a alternativa correta sobre a conduta?"}}},{"id":"revalida_2021_1_q024","code":"REV-2021-Q024","campos":{"statement":{"antes_md5":"2e50140538223f39bb68a9f650f3930a","depois":"Uma mulher com 61 anos de idade, acompanhada pela filha, foi atendida em ambulatório de hospital secundário referindo ter apresentado dor no hipocôndrio direito e vômitos por 3 dias, há 30 dias. Relatava fazer uso de metformina 500 mg, 2 vezes por dia e atenolol 50 mg por dia. Trouxe ultrassonografia que descrevia vesícula biliar com paredes discretamente espessadas e presença de colelitíase. Os exames laboratoriais evidenciaram glicemia de 120 mg/dL (referência: 75 a 99), creatinina 0,99 mg/dL (referência: 0,6 a 1,1), leucócitos 6 200/mm³ (referência: 3 500 a 10 500), não apresentava alteração na contagem diferencial dos leucócitos. Ao exame físico, o abdome estava flácido, não relatava dor à palpação, PA = 140/80 mmHg, temperatura axilar = 36,5 ºC. Com base nos dados apresentados, qual alternativa apresenta a orientação correta à paciente e à filha sobre a conduta a ser seguida?"}}},{"id":"revalida_2021_1_q026","code":"REV-2021-Q026","campos":{"statement":{"antes_md5":"c342bac46d15acf82cfbddb3d47fef4d","depois":"Um paciente do sexo masculino, de 3 anos de idade, é levado a serviço de emergência em decorrência de febre e exantema há 7 dias. Mãe relata que a febre é diária e chegou a 39 ºC. O exantema surgiu há 2 dias. O paciente já passou por outros serviços de emergência sem conseguir fechar diagnóstico. Nega doenças prévias. Desenvolvimento normal para a idade. Ao exame, mostra-se em regular estado geral, descorado 1+/4+, febril (38,5 ºC), acianótico e hidratado. Presença de exantema maculopapular e edema e hiperemia nas mãos e pés, rash em tronco e períneo, bem como de hiperemia conjuntival bilateral. Cavidade oral revela fissuras em lábios. Há linfonodomegalia cervical, unilateral direita, com 2 cm de diâmetro. Aparelho cardiovascular, respiratório e abdome sem anormalidades. Considerando a história acima descrita, assinale a alternativa que contém o tratamento indicado."}}},{"id":"revalida_2021_1_q027","code":"REV-2021-Q027","campos":{"statement":{"antes_md5":"2d844be425f9a3b078932f2ded1e446a","depois":"Um homem de 23 anos de idade, membro de um grupo de usuário de drogas ilícitas injetáveis, comparece à consulta no ambulatório de clínica médica com relato de \"olhos amarelos e urina cor de mate\". Segundo informa, seu quadro clínico iniciou-se há cerca de 12 dias com mal-estar, febre (cerca de 38 ºC), coriza e mialgias. Dois dias após, observou disgeusia e anosmia, além de diarreia. Procurou unidade de pronto atendimento, sendo agendada pesquisa para COVID-19, que foi realizada no 5.º dia de evolução da doença, com resultado negativo. Passou a apresentar, também, dor abdominal (especialmente no hipocôndrio direito) e fadiga vespertina. Há 2 dias, observou que suas escleras ficaram amareladas e a sua urina assumiu aspecto sugestivo de colúria. Foi à mesma unidade onde havia sido atendido inicialmente, sendo solicitados exames complementares que são trazidos pelo paciente à consulta atual e que revelam: TGO/AST = 982 UI/L (valor de referência: 20 a 40 UI/L); ALT/TGP: 1 220 UI/L (valor de referência: 20 a 40 UI/L); bilirrubinas totais = 4,2 mg/dL (valor de referência: 0,2 a 0,8 mg/dL), com predomínio da fração direta (3,6 mg/dL - valor de referência: 0,1 a 0,5 mg/dL); hemograma com leucopenia e linfocitose, sem anemia; INR e tempo de tromboplastina parcial ativada normais. Em razão desses resultados, o paciente foi encaminhado ao ambulatório para complementação da investigação diagnóstica, tratamento e acompanhamento. Ao exame físico, o paciente encontra-se em razoável estado geral, estando com as escleras e a mucosa sublingual ictéricas, além de apresentar leve hepatomegalia (13 cm de extensão ao nível da linha hemiclavicular direita) dolorosa, com sinal de Murphy negativo. Acerca do caso desse paciente, pode-se afirmar que o diagnóstico mais provável e a lógica subjacente a tal conclusão são"}}},{"id":"revalida_2021_1_q033","code":"REV-2021-Q033","campos":{"D":{"antes_md5":"b346121a1c1f9bedde253a54bb647ed3","depois":"Cisto do 3.º arco branquial. Ressecção cirúrgica incluindo a secção do ramo clavicuar do músculo esternocleidomastoídeo."}}},{"id":"revalida_2021_1_q041","code":"REV-2021-Q041","campos":{"statement":{"antes_md5":"7b44a4942f1abff8843ed20910e200a5","depois":"A figura a seguir apresenta a mortalidade proporcional por alguns grupos de causa no sexo masculino e em grupos etários selecionados. Legenda: DIC – Doenças Isquêmicas do Coração DCV – Doenças Cerebrovasculares ODC – Outras Doenças Coronarianas IP – Influenza e Pneumonia ODR – Outras Doenças Respiratórias DF – Doenças do Fígado ATR – Acidentes de Transporte EII – Eventos com intenção indeterminada AG – Agressões AS – Afogamentos e/ou submersões LAI – Lesões Autoinfligidas Fonte: DATASUS, MS, 2021. (acesso em 01/07/2021). Figura 1. Mortalidade proporcional (%) por grupos de causas e em faixas etárias selecionadas, no sexo masculino, Brasil, 2019. Com base nos dados demonstrados nos gráficos, conclui-se que"}}},{"id":"revalida_2021_1_q042","code":"REV-2021-Q042","campos":{"statement":{"antes_md5":"5efc9538d1837bda21693337b14dfc1d","depois":"Paciente do sexo masculino, 65 anos, foi atendido no serviço de urgência de um hospital com queixa de dor em flanco e fossa ilíaca esquerdos, com início há cerca de 48 horas e piora nas últimas 12 horas. Neste período, apresentou episódio febril de 38 ºC, aferido em seu domicílio. Relatou apresentar divertículos do cólon há cerca de 12 anos, e que foi submetido a uma gastrectomia parcial há 1 ano por adenocarcinoma gástrico em antro, estágio IB. Apresentou relatório médico relativo a esse procedimento, no qual constava endoscopia digestiva alta com biópsia confirmando o diagnóstico histológico, tomografia computadorizada de abdome e tórax, que revelava doença diverticular em sigmoide, e colonoscopia confirmando doença diverticular em sigmoide. Ao exame físico, o paciente estava em bom estado geral, frequência cardíaca de 95 bpm, pressão arterial de 130 x 80 mmHg e temperatura axilar de 38,1 ºC. O abdome estava flácido, mas doloroso à palpação profunda de flanco e fossa ilíaca esquerdos e hipogástrio. Hemograma revelou leucocitose de 16 000/mm³ (referência: 9 000 – 11 000/mm³) com 10% de bastões (referência: 0 – 5%). O paciente relatou estar preocupado pela possibilidade de ser um “retorno do câncer”. O exame complementar e explicação para confirmação do diagnóstico nesse momento é"}}},{"id":"revalida_2021_1_q046","code":"REV-2021-Q046","campos":{"statement":{"antes_md5":"753af94f93344381a185b410a4cc2242","depois":"Um homem de 57 anos de idade comparece ao ambulatório de clínica médica de hospital de média complexidade para avaliação diagnóstica de quadro de fraqueza, cansaço, adinamia e desequilíbrio nos membros inferiores (MMII). Segundo informa, seu estado geral era bom até 3 meses antes, quando passou a perceber fraqueza e adinamia. Pensou ser decorrente do hipotireoidismo, mas após reavaliação hormonal, sua endocrinologista informou-lhe que a tireoidite de Hashimoto estava bem controlada, não sendo necessário nenhum reajuste da dose de levotiroxina em uso crônico (125 mcg/dia). Como os sintomas persistiram, procurou facultativo que lhe solicitou um hemograma completo, cujo resultado revelou o seguinte padrão: hemoglobina: 7,6 g/dL (valor de referência: 13 a 16,5 g/dL); hematócrito: 26% (valor de referência: 40 a 52%); hemácias: 2,3 x 10⁶/mcl (valor de referência: 4,5 a 6,0 x 10⁶/mcl); volume corpuscular médio: 113 fl (valor de referência: 80 a 100 fl); leucócitos: 2 800/mcl (valor de referência: 6 000 a 10 000/mcl), com contagem diferencial normal; plaquetas: 86 000/mcl (valor de referência: 150 a 400 x 10³/mcl). Ao exame físico procedido na consulta, o paciente encontra-se bastante pálido, ictérico (+/4+), normotenso, levemente taquicárdico (104 bpm) e hidratado; exame do aparelho cardiovascular revela apenas sopro sistólico pancardíaco, enquanto o exame do aparelho respiratório e do abdome é normal. Contudo, ao exame neurológico, é observada perda da propriocepção consciente e da sensibilidade vibratória nos MMII, sendo o reflexo cutâneo-plantar em extensão bilateral. Uma hematoscopia realizada durante o exame no ambulatório revela a presença de plurissegmentação dos neutrófilos. A etiologia mais provável da anemia do paciente em apreço é"}}},{"id":"revalida_2021_1_q053","code":"REV-2021-Q053","campos":{"statement":{"antes_md5":"f92dbd6b6739785089dcf059990e3439","depois":"Um paciente de 35 anos de idade, vivendo com HIV/AIDS há alguns anos, sem adesão à terapia antirretroviral indicada (TARV), é internado em hospital de média complexidade com quadro de tosse produtiva, febre e dor torácica, associados à imagem radiológica compatível com condensação em base direita, sendo iniciado tratamento com amoxicilina-clavulanato. Revendo os exames de admissão do paciente, o médico que o atende percebe que o infiltrado radiológico evolui com áreas de cavitação, o que o leva a considerar a hipótese diagnóstica de tuberculose pulmonar atípica, decorrente da presença de imunossupressão. Visando a proceder à investigação diagnóstica indicada no caso, a recomendação atual da Organização Mundial de Saúde é que o teste diagnóstico de 1.ª linha para tais pacientes com doença pulmonar ativa, tendo ainda a vantagem de detectar resistência antimicrobiana, seria"}}},{"id":"revalida_2021_1_q056","code":"REV-2021-Q056","campos":{"statement":{"antes_md5":"2183e1ca0f91f274d3f7f5a9e388e3d3","depois":"Paciente de 60 anos de idade, masculino, procura hospital pronto-socorro com história de parada de eliminação de flatos e fezes há cerca de 1 semana. Nega vômitos. Ao exame físico, paciente em regular estado geral, desidratado, dispneico, taquicárdico. Abdome globoso, hipertimpânico, doloroso à palpação difusa, com sinais de irritação peritoneal. Toque retal com ampola retal vazia, sem fezes, sem muco, sem sangue em “dedo-de-luva”. Solicitadas radiografias de tórax e abdome, demonstrando distensão volumosa de cólon e ceco (maior que 12 cm), com níveis hidroaéreos, sem distensão de intestino delgado. Baseado nessas informações, qual a conduta?"}}},{"id":"revalida_2021_1_q059","code":"REV-2021-Q059","campos":{"A":{"antes_md5":"0ea2ca8aafdec0ebe6ab62e10f3ad0ff","depois":"Manutenção do aleitamento materno com uso de máscara por parte da mãe e uso profilático de isoniazida até o 3.º mês de vida, quando o teste tuberculínico deverá ser realizado."},"B":{"antes_md5":"d657899caadcb4368a11ef4915177620","depois":"Interrupção do aleitamento materno por parte da mãe e uso profilático de isoniazida até o 3.º mês de vida, quando o teste tuberculínico deverá ser realizado."},"C":{"antes_md5":"fa930f5f64eea3ca517811d26795ffa3","depois":"Manutenção do aleitamento materno com uso de máscara por parte da mãe e uso profilático de isoniazida até o 6.º mês de vida, quando o teste tuberculínico deverá ser realizado."},"D":{"antes_md5":"f56a636f9e91664a73f0d875d6514bb2","depois":"Interrupção do aleitamento materno por parte da mãe e uso profilático de isoniazida até o 6.º mês de vida, quando o teste tuberculínico deverá ser realizado."}}},{"id":"revalida_2021_1_q061","code":"REV-2021-Q061","campos":{"statement":{"antes_md5":"ae87758e7207c4f48c78f860bfb71932","depois":"Uma lactente de 13 meses de idade, de sexo feminino, é levada à Unidade Básica de Saúde para consulta de rotina. A mãe está preocupada, pois a criança ainda não é capaz de andar sem apoio. Não há outras queixas. O pré-natal materno não possui intercorrências; nasceu de parto normal, com 40 semanas de idade gestacional; Boletim de Apgar no 1.º minuto = 6; no 5.º minuto = 9; e no 10.º minuto = 10; com peso ao nascer = 3 200 g e comprimento ao nascer = 50 cm. No exame clínico neonatal, observou-se estalido à manobra de Ortolani à direita; na ocasião, realizou exame ultrassonográfico de quadril apresentando resultado I pelo método de Graf. Recebeu alta no segundo dia de vida. Sem antecedentes pessoais ou familiares relevantes. Desenvolvimento neuropsicomotor prévio: sorriso social aos 2 meses; fixou o pescoço aos três meses; sentou sem apoio aos sete meses; passou a distinguir familiares de estranhos e a reconhecer seu nome aos nove meses; primeiras palavras com significado aos 11 meses. Atualmente engatinha, fica em pé com apoio das mãos e arrisca alguns passos sem apoio, mas logo cai; usa copo com ajuda, compreende ordens simples, bate palma, manda beijo, fala “mama” e “papa” para referir-se à mãe e ao pai respectivamente. Não apresenta alterações ao exame clínico. A conduta adequada para essa criança, considerando o desenvolvimento da marcha é"}}},{"id":"revalida_2021_1_q063","code":"REV-2021-Q063","campos":{"statement":{"antes_md5":"549a593d63aa95c37e130257a5a401f7","depois":"Paciente de 50 anos de idade, masculino, obeso, diabético, hipertenso, procura hospital pronto-socorro com queixa de dispneia aos pequenos esforços há 4 dias. Tosse não-produtiva. Febre não-mensurada. Refere anosmia e ageusia. Ao exame, paciente em mal estado geral, taquidispnéico, taquicárdico, tossindo, com tiragem intercostal e supraesternal. Submetido a tomografia de tórax de urgência, demonstrando mais de 70% de imagens “em vidro-fosco” no parênquima pulmonar, bilateralmente. Saturação de O₂ de 60% em ar ambiente. O médico assistente optou por internação hospitalar de urgência e subsequente intubação orotraqueal, na mesma data da internação. Duas tentativas de extubação, sem sucesso, após 2 dias de intubação. Com base nas informações fornecidas, qual o momento para indicar uma traqueostomia para esse paciente?"}}},{"id":"revalida_2021_1_q068","code":"REV-2021-Q068","campos":{"statement":{"antes_md5":"9f852e63afd773f0072b5d7dce45bfa3","depois":"Um recém-nascido de 15 dias é levado à primeira consulta de puericultura. A gestação correu sem intercorrências. Mãe relata ser asmática e fez uso de prednisona oral durante toda a gestação. Parto vaginal a termo. Peso de nascimento = 3 500 g. Apgar 9/9. Alta com 2 dias. Colheu teste do pezinho no 4.º dia de vida. Ao exame, o recém-nascido mostra-se em ótimo estado geral, corado e hidratado. O exame cardiovascular e respiratório sem anormalidades, assim como o exame do abdome. Considerando a história acima, assinale a alternativa que apresenta a doença cujo resultado no teste de triagem neonatal pode ter seu resultado modificado pela condição clínica materna descrita."}}},{"id":"revalida_2021_1_q075","code":"REV-2021-Q075","campos":{"statement":{"antes_md5":"26da0075822dafac4b9ba04db6403fb0","depois":"Um homem de 67 anos de idade, tabagista inveterado (carga tabágica = 82 maços-ano), retorna ao ambulatório de clínica médica para trazer os resultados dos exames complementares que haviam sido solicitados na sua última consulta, quando havia se queixado de dispneia aos esforços e tosse crônica produtiva. Reunindo os dados da anamnese e do exame físico, o médico que o atendera considerou como mais provável o diagnóstico de doença pulmonar obstrutiva crônica (DPOC), solicitando, entre outros exames, a realização de uma espirometria. No resultado desse exame, foram registrados os valores do volume expiratório forçado no 1.º segundo (VEF₁), da capacidade vital (CVF), da relação VEF₁/CVF, do FEF25-75 (fluxo medioexpiratório forçado entre 25% e 75% da CVF) e a resposta ao estímulo com broncodilatador (REB). Para confirmar tal impressão diagnóstica, o resultado que deve estar indispensavelmente presente em sua espirometria é"},"B":{"antes_md5":"0ac9b4b58f2ebf335a42d26841d054fe","depois":"REB com aumento do VEF₁ maior que 200 mL."},"C":{"antes_md5":"54138538b7a27125e2b59562299cb861","depois":"VEF₁ inferior a 80% do previsto antes ou após broncodilatador."},"D":{"antes_md5":"5309fb837628bfc0aca0579634debe6a","depois":"VEF₁/CVF inferior a 0,7 mesmo após broncodilatador."}}},{"id":"revalida_2021_1_q076","code":"REV-2021-Q076","campos":{"statement":{"antes_md5":"d75e8e854105c4d3a5ff2dd692cc623b","depois":"Paciente de 40 anos de idade, sexo feminino, procura unidade pública de pronto atendimento com queixa de dor em ferida operatória de ressecção de “nódulo” de 5 cm de diâmetro, na região escapular direita, há 2 dias. Ao exame, ferida cirúrgica com edema, eritema, calor e dor à palpação, associada a flutuação e exsudação em bordos da sutura. Com base nas informações, qual a conduta propedêutico-terapêutica para essa paciente?"}}},{"id":"revalida_2021_1_q079","code":"REV-2021-Q079","campos":{"statement":{"antes_md5":"39e83c0fc75c10c96e5bb41091df8516","depois":"Uma mulher de 38 anos de idade é admitida na enfermaria de cardiologia de hospital de alta complexidade, em função de quadro de dispneia progressiva, ortopneia e dispneia paroxística noturna. Segundo a paciente informa, seus sintomas anteriores iniciaram-se há cerca de 1 ano, tendo progredido ao longo do período. Procurou assistência médica em algumas ocasiões, sendo finalmente internada para realização de exames complementares e definição diagnóstica. Em sua história patológica pregressa, há relato de dois episódios de febre reumática na adolescência, num dos quais foi detectado um \"sopro no coração\". Fez uso de penicilina benzatina de forma mensal, mas irregular, até os 18 anos de idade. Nega outros dados relevantes de anamnese. Ao exame físico, paciente está em bom estado geral, em atitude ortopneica. Não há febre. PA = 120 x 70 mmHg; FC = 87 bpm. Ritmo cardíaco é irregular, em 2 tempos, com 1.ª bulha hiperfonética e presença de sopro diastólico (2+/6+) em ponta, melhor audível em semi-decúbito lateral esquerdo; um ruído protodiastólico curto, de alta frequência, é também auscultado no foco mitral, mas não se observa reforço do ruflar diastólico. Há anicardiosfigmia. Não é detectada turgência jugular a 45°. Estertores crepitantes finos são auscultados em bases. Não há congestão hepática, nem edema de MMII. Exames complementares iniciais (incluindo VHS) revelam-se normais, sendo a pesquisa de ASLO e swab de orofaringe negativos para infecção por Streptococcus pyogenes. Eletrocardiograma revela ritmo de fibrilação atrial, com QT normal. Diante dos dados relatados, a melhor explicação para o quadro da paciente é"}}},{"id":"revalida_2021_1_q080","code":"REV-2021-Q080","campos":{"statement":{"antes_md5":"e1f08784c71a73c3949a05a0850f0218","depois":"Uma mulher, com 23 anos de idade, 1.º trimestre de gestação, primigesta, comparece à primeira consulta de pré-natal na Unidade de Estratégia de Saúde da Família. Testes rápidos para sífilis, HIV, hepatite B e hepatite C não reagentes. A conduta com relação à solicitação desses exames no seguimento pré-natal da gestante, de acordo com o Ministério da Saúde, é repetir"},"A":{"antes_md5":"4fe3989ac6e9c88fbe52ba8afc5e9267","depois":"a testagem para sífilis e HIV no 3.º trimestre de gestação, no parto e/ou se história de exposição de risco/violência sexual."},"B":{"antes_md5":"a442578bdbe5371effd70a8a1b96395f","depois":"todas as testagens (sífilis, HIV, hepatite B e hepatite C) no 3.º trimestre de gestação, no parto e/ou se história de exposição de risco/violência sexual."},"C":{"antes_md5":"35a5ec43108adb8483fe152d20bc34a5","depois":"a testagem para hepatite B no 3.º trimestre se a gestante tiver histórico de vacinação e se Anti-HBc total for reagente é desnecessária sua repetição no parto."},"D":{"antes_md5":"e651a5d4aec47df62a52664bb96ff4ef","depois":"a testagem para hepatite C no 2.º e 3.º trimestres, além do parto e/ou se história de exposição de risco/violência sexual."}}},{"id":"revalida_2021_1_q081","code":"REV-2021-Q081","campos":{"statement":{"antes_md5":"9c60e027170ef4bb4dfff35397086bb5","depois":"Uma mulher de 29 anos de idade procura a maternidade com queixa de sangramento vaginal tipo \"borra de café\". Estava na 32.ª semana de gestação, tônus uterino, movimentação e batimentos cardíacos fetais normais. No toque não foi observado sangramento. Gesta 3; para 3. Exames laboratoriais normais. Tipo sanguíneo O negativo e do marido A positivo. Não apresentou cartão pré-natal e não tinha nenhum exame em sua posse. Diante da situação apresentada, a conduta a ser adotada é"}}},{"id":"revalida_2021_1_q082","code":"REV-2021-Q082","campos":{"statement":{"antes_md5":"950667d3e49a1dff7a0ea9cfd46860ad","depois":"No atendimento de urgências por queimaduras, a avaliação da extensão da superfície corporal queimada (SCQ) do paciente pode ser feita pela “regra dos nove\", diagrama de Lund e Browder e, mais recentemente, com uso de aplicativos em smartphones. Utilizando a regra dos nove em um paciente masculino de 60 anos, pesando 50 Kg, com queimadura de 3.º grau que atinge a totalidade do membro superior direito e a totalidade do membro inferior esquerdo, tem-se, respectivamente, a superfície corporal estimada e a reposição hídrica, segundo a fórmula de Parkland, de"}}},{"id":"revalida_2021_1_q085","code":"REV-2021-Q085","campos":{"statement":{"antes_md5":"ac868c1053eac12456d0941b96c42035","depois":"Mulher, 28 anos de idade, professora, com 2 gestações anteriores, sendo um parto normal e um aborto espontâneo anteriormente. Tem um filho de 7 anos de idade de outro relacionamento. Há 2 anos está casada com homem de 35 anos, sem filhos. Ambos sem antecedentes patológicos significativos. Referem que há vários anos não procuram assistência com a equipe de saúde. O exame físico do casal revelou como únicos achados positivos em relação à mulher: PA = 140 x 85 mmHg e índice de massa corporal de 30 Kg/m². Exame físico do homem foi normal. Estavam em uso de preservativo e pílula combinada, mas interromperam há 2 semanas. Vão em busca de orientação pré-concepcional. Nesta situação, está indicado(a)"}}},{"id":"revalida_2021_1_q086","code":"REV-2021-Q086","campos":{"statement":{"antes_md5":"fb75a0c0271e94b52f6828a0667d206c","depois":"Uma mulher de 27 anos de idade, de etnia afrodescendente, retorna ao ambulatório de clínica médica para mostrar os resultados dos exames complementares solicitados na última consulta. A paciente havia sido atendida em função de sintomas constitucionais (febre intermitente, mal-estar, anorexia, desânimo e artralgias) e importante queda de cabelos. Ao exame físico, havia sido observada a presença de sinovite em punhos, cotovelos, joelhos e tornozelos. Além de padrão de alopecia generalizada (eflúvio telógeno). Havia histórico familiar de artrite reumatoide, lupus eritematoso e tireoidite de Hashimoto. A paciente negava tabagismo e etilismo, referindo apenas uso regular de contraceptivo hormonal oral. Os resultados dos exames complementares solicitados à ocasião da 1.ª consulta revelaram: hemoglobina = 10,2 g/dL (valor de referência: 12 a 15,5 g/dL); contagem de plaquetas = 102 000/mm³ (valor de referência: 150 000 a 400 000/mm³); leucograma (incluindo diferencial) normal; TSH = 8 UI/ml (valor de referência: 0,5 a 5,0 UI/ml); T4 livre = 1,2 ng/dL (valor de referência: 0,9 a 1,9 ng/dL); FAN = presente em título 1:640 (valor de referência < 1:80), padrão periférico; anti-DNAds: presente em título 1:240 (valor de referência < 1:100); C3: 33 mg/dL (valor de referência: 90 a 180 mg/dl); VDRL + 1:4 (valor de referência: negativo); IgG anticardiolipina: 12 GPL (valor de referência < 10 GPL); ureia: 44 mg/dL (valor de referência: 20 a 40 mg/dL); creatinina = 1,2 mg/dL (valor de referência: 0,7 a 1,1 mg/dL); exame de urina tipo I com hematúria microscópica e proteinúria leve a moderada; SPOT urinário com proteinúria estimada de 560 mg (valor de referência < 151 mg). Diante dos dados apresentados, a melhor explicação diagnóstica para o caso é"}}},{"id":"revalida_2021_1_q087","code":"REV-2021-Q087","campos":{"statement":{"antes_md5":"06d1aed3f95eea8d84f6657327146a8f","depois":"Uma gestante, com 28 anos de idade, na 14.ª semana de gestação, primigesta, em consulta com equipe de Estratégia de Saúde da Família para avaliação de exames de pré-natal apresenta IgG e IgM reagentes para toxoplasmose, sem resultado de exames prévios. Solicitado teste de avidez de IgG na mesma amostra, com resultado “avidez forte”. A interpretação do resultado e a conduta são"}}},{"id":"revalida_2021_1_q093","code":"REV-2021-Q093","campos":{"statement":{"antes_md5":"4b90a8edefc8655c3f2022c1cea81a67","depois":"Uma mulher de 34 anos de idade é atendida em pronto-socorro com desconforto abdominal, sem sinais de peritonite, com atraso menstrual de 3 semanas. Foi submetida à terceira tentativa de inseminação artificial, recentemente, e apresentava beta-hCG = 3 000 mUI/mL, dosado no dia anterior. O médico solicitou uma ultrassonografia que evidenciou gestação ectópica à esquerda, com saco gestacional bem delimitado, sem batimentos cardíacos fetais e medindo 3 cm. Diante do quadro atual, qual a conduta apropriada?"},"A":{"antes_md5":"2a045f5d01f313cccdb064200b81dbd7","depois":"Iniciar tratamento com metotrexato 50 mg/m²."}}},{"id":"revalida_2021_1_q098","code":"REV-2021-Q098","campos":{"D":{"antes_md5":"a26b8039116398333fdbc781d4697819","depois":"compartilha da visão ampliada do processo saúde-doença e a promoção global do cuidado humano, especialmente do autocuidado."}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2021', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2021', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2021', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2021: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 40)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2021'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2021' and situacao like 'pulado%'
) x order by ordem, resultado;
